import React from 'react';
import { useParams } from 'react-router-dom';
import Header from './Header';

const UserDetails = () => {
  const { id } = useParams();

  // Fetch user details here based on the ID
  return (
    <div>
      <Header />
      <main>
        <h2>User Details</h2>
        <p>User ID: {id}</p>
        {/* Display other user details here */}
      </main>
    </div>
  );
};

export default UserDetails;
